import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    a = data[1:1+n]
    last = {}
    ans = float('inf')
    for i, v in enumerate(a):
        if v in last:
            gap = i - last[v] + 1
            if gap < ans:
                ans = gap
            last[v] = i
        else:
            last[v] = i
    print(ans if ans != float('inf') else -1)

main()
