import sys

def main():
    S = sys.stdin.readline().strip()
    res = []
    for c in S:
        if c == 'A' and res and res[-1] == 'W':
            k = 0
            while res and res[-1] == 'W':
                res.pop()
                k += 1
            res.append('A')
            res.append('C' * k)
        else:
            res.append(c)
    sys.stdout.write(''.join(res) + '\n')

main()

