def main():
    import sys
    N = int(sys.stdin.readline())
    grid = [['?'] * N for _ in range(N)]
    for i in range(1, N + 1):
        j = N + 1 - i
        if i > j:
            continue
        c = '#' if i % 2 == 1 else '.'
        for r in range(i, j + 1):
            for col in range(i, j + 1):
                grid[r - 1][col - 1] = c
    print('\n'.join(''.join(row) for row in grid))

main()
