import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    C = input_data[1:1+n]

    INF = -1
    dist = [[-1]*n for _ in range(n)]

    # incoming[u][letter] = list of x such that edge x->u labeled letter
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]

    for i in range(n):
        row = C[i]
        for j in range(n):
            ch = row[j]
            if ch != '-':
                a = ord(ch) - 97
                outgoing[i][a].append(j)
                incoming[j][a].append(i)

    dq = deque()
    for i in range(n):
        dist[i][i] = 0
        dq.append((i, i))
    for i in range(n):
        for a in range(26):
            for j in outgoing[i][a]:
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    dq.append((i, j))

    while dq:
        u, v = dq.popleft()
        d = dist[u][v]
        nd = d + 2
        for a in range(26):
            ins = incoming[u][a]
            outs = outgoing[v][a]
            if not ins or not outs:
                continue
            for x in ins:
                drow = dist[x]
                for y in outs:
                    if drow[y] == -1:
                        drow[y] = nd
                        dq.append((x, y))

    out = []
    for i in range(n):
        out.append(' '.join(map(str, dist[i])))
    sys.stdout.write('\n'.join(out) + '\n')

main()
