import sys

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); R = int(data[1]); C = int(data[2])
    S = data[3].decode()
    seen = {(0, 0)}
    r = 0
    c = 0
    out = []
    for ch in S:
        if ch == 'N':
            r -= 1
        elif ch == 'S':
            r += 1
        elif ch == 'W':
            c -= 1
        else:  # 'E'
            c += 1
        if (r - R, c - C) in seen:
            out.append('1')
        else:
            out.append('0')
        seen.add((r, c))
    sys.stdout.write(''.join(out) + '\n')

main()
